{"src/exportCsv.mjs":"/** rows为对象数组，返回可用于下载的字符串。 */
export function exportCsv(rows) {
  const list = Array.isArray(rows) ? rows : [];

  // 收集所有出现过的字段名，保持首次出现顺序，避免遗漏外部填写带来的新字段。
  const columns = [];
  const seen = new Set();
  for (const row of list) {
    if (row === null || typeof row !== "object") continue;
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        columns.push(key);
      }
    }
  }

  const escapeCell = (value) => {
    let text;
    if (value === null || value === undefined) {
      text = "";
    } else if (typeof value === "object") {
      // 嵌套对象/数组序列化为 JSON，避免出现 [object Object]。
      try {
        text = JSON.stringify(value);
      } catch {
        text = String(value);
      }
    } else {
      text = String(value);
    }

    // 防止外部内容被表格软件当作公式执行。
    if (/^[=+\-@\t\r]/.test(text)) {
      text = "'" + text;
    }

    if (/[",\r\n]/.test(text)) {
      text = '"' + text.replace(/"/g, '""') + '"';
    }
    return text;
  };

  const lines = [];
  lines.push(columns.map(escapeCell).join(","));
  for (const row of list) {
    const source = row !== null && typeof row === "object" ? row : {};
    lines.push(columns.map((key) => escapeCell(source[key])).join(","));
  }

  // 带 BOM，便于表格软件正确识别 UTF-8 中文。
  return "\uFEFF" + lines.join("\r\n") + "\r\n";
}
